package com.sathavahana.kalamkari.service;
import com.sathavahana.kalamkari.domain.*; import com.sathavahana.kalamkari.dto.CartDto; import com.sathavahana.kalamkari.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CartService {private final CartRepository carts; private final ProductRepository products; private final CurrentUser current; private final UserRepository users; public CartService(CartRepository c,ProductRepository p,CurrentUser u,UserRepository ur){carts=c;products=p;current=u;users=ur;} @Transactional public CartDto get(){var u=current.require(); return CartDto.of(carts.findByUserId(u.getId()).orElseGet(()->carts.save(new Cart(u))));} @Transactional public CartDto add(Long productId,int quantity){if(quantity<1)throw new IllegalArgumentException("quantity must be positive"); var u=current.require(); var c=carts.findByUserId(u.getId()).orElseGet(()->carts.save(new Cart(u))); var p=products.findById(productId).orElseThrow(()->new NotFoundException("Product not found")); var item=c.getItems().stream().filter(i->i.getProduct().getId().equals(productId)).findFirst().orElse(null); if(item==null)c.getItems().add(new CartItem(c,p,quantity)); else item.setQuantity(item.getQuantity()+quantity); return CartDto.of(carts.save(c));}}
